let globalVar = "Я глобальная";  // доступна везде

function showScope() {
  let localVar = "Я локальная";  // видна только внутри функции
  console.log(globalVar);  // "Я глобальная" — видна изнутри
  console.log(localVar);   // "Я локальная" — видна
}

showScope();
console.log(globalVar);  // "Я глобальная" — доступна снаружи
// console.log(localVar);  // ReferenceError! localVar не видна снаружи

// let/const — блочная область:
if (true) {
  let blockScoped = "внутри блока";
  const blockConst = "тоже внутри";
}
// console.log(blockScoped);  // ReferenceError — не видно снаружи

// var — ИГНОРИРУЕТ блоки, это функциональная область:
if (true) {
  var leaky = "вытек из блока";
}
console.log(leaky);  // "вытек из блока" — var вылез!

