// var: ОДНА переменная на все итерации
for (var i = 0; i < 3; i++) {
  setTimeout(() => {
    console.log(i);  // 3, 3, 3 — цикл завершился, i = 3
  }, 0);
}

// let: НОВАЯ переменная на каждую итерацию
for (let i = 0; i < 3; i++) {
  setTimeout(() => {
    console.log(i);  // 0, 1, 2 — каждая итерация со своим i
  }, 0);
}

// Почему: let создаёт отдельную копию i для каждой итерации,
// а var — одну переменную, которая меняется на глазах.

// Функция создаёт и возвращает другую функцию
function createCounter() {
  let count = 0;  // локальная переменная

  return function() {
    count++;  // функция ЗАПОМНИЛА count из внешней области
    return count;
  };
}

const counter = createCounter();
// createCounter завершилась, но count живёт внутри counter
console.log(counter());  // 1
console.log(counter());  // 2
console.log(counter());  // 3
// count недоступна снаружи — это приватная переменная!

