theory.content:
let global = "глобальная";

function outer() {
  let outerVar = "внешняя";

  function inner() {
    let innerVar = "внутренняя";
    console.log(innerVar);  // найдена локально
    console.log(outerVar);  // найдена в outer
    console.log(global);    // найдена глобально
  }

  inner();
}

outer();
// innerVar -> outerVar -> global — цепочка поиска

// ВАЖНО: ищется в месте СОЗДАНИЯ функции, а не вызова!

// ПЛОХО: глобальная переменная
let counter = 0;
function increment() {
  counter++;  // любая функция может изменить counter
}

// ХОРОШО: приватная переменная через замыкание
function createCounter() {
  let counter = 0;  // приватная!
  return {
    increment() { counter++; },
    getValue() { return counter; }
  };
}

const c = createCounter();
c.increment();
console.log(c.getValue());  // 1
// counter недоступна снаружи — безопасно!

